insert into hr.employers(company_id,setup_status) select id,'setup' from public.store_business_identity on conflict(company_id) do nothing;
insert into hr.payroll_config_versions(company_id,tax_year,effective_from,source_name,source_url,config,status,verified_at)
insert into hr.compliance_tasks(company_id,task_type,title,due_at,guidance_version) select company_id,'system_setup','Verify employer HR/payroll configuration before employee onboarding',now()+interval '30 days','CentralHub HR setup 2026-09' from hr.employers e where not exists(select 1 from hr.compliance_tasks t where t.company_id=e.company_id and t.task_type='system_setup');